{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Safinamide, a close analogue with an arylmethylamine, fluoroaromatic ring, and amide, has a measured absolute oral bioavailability of 95% in humans, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rolipram, which contains a lactam and aromatic substituents similar to the query, shows an absolute oral bioavailability of 73 ± 25% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Aprepitant, a fluorinated aromatic drug with amide/lactam-like features, has a mean absolute oral bioavailability of 60–65% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Irbesartan, a biaryl/heteroaryl drug with high transferability, has an absolute oral bioavailability of approximately 80% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Thalidomide, containing an imide/lactam core, has a probably high oral bioavailability of 80–100% in humans, supporting high F for the lactam-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Balcinrenone, which shares a lactam and fluoroaromatic motif, has an absolute oral bioavailability of 52% in humans, still well above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved high-transfer analogues show absolute oral bioavailability values of at least 50% in humans, and the query shares relevant structural features such as arylmethylamine, fluoroaromatic, and lactam/amide motifs. No affirmative evidence for low bioavailability was retrieved, so the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct experimental absolute bioavailability measurement is available for the query molecule.",
    "No retrieved analogue with low oral bioavailability was available to test the negative direction.",
    "Potential first-pass metabolism or transporter effects specific to the methylamino group were not directly assessed."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C38"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "arylmethylamine/fluoroaromatic amide analogues"
    }
  ],
  "revision_action": "initial"
}

